#include "d2_runtime.h"
#include <string.h>
void d2_runtime_init(D2Runtime *r,const D2DeviceIo *io,uint64_t b0,uint64_t b1,uint64_t bw0,uint64_t bw1){if(!r)return;memset(r,0,sizeof(*r));d2_locality_init(&r->locality);d2_residency_init(&r->residency,b0,b1,bw0,bw1);d2_stream_init(&r->stream,&r->residency.counters);if(io)r->io=*io;}
int d2_runtime_stage_plan(D2Runtime *r,const D2TokenPlan *p){size_t i;if(!r||!p)return D2_EINVAL;for(i=0;i<p->count;i++){size_t idx;if(d2_residency_find(&r->residency,p->item[i].device,p->item[i].range.tensor_id,&idx)==D2_OK)continue;int rc=d2_stream_push(&r->stream,&p->item[i].range,p->item[i].device,0);if(rc)return rc;}return D2_OK;}
int d2_runtime_pump_one(D2Runtime *r,uint64_t token){D2StreamReq q;size_t slot;int rc;if(!r||!r->io.load_exact)return D2_EINVAL;rc=d2_stream_pop(&r->stream,&q);if(rc)return rc;rc=d2_residency_reserve(&r->residency,&r->locality,q.device,q.range.tensor_id,q.range.expert_id,q.range.bytes,token,&slot);if(rc){d2_stream_complete(&q,rc);return rc;}rc=r->io.load_exact(r->io.ctx,q.device,&q.range,q.ticket);if(rc){r->residency.counters.device_load_fail[q.device]++;d2_stream_complete(&q,D2_EIO);return D2_EIO;}rc=d2_residency_commit(&r->residency,&r->locality,q.device,slot);d2_stream_complete(&q,rc);return rc;}
